// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint amount) public {
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(0));
        uint256 amountBound = bound(amount, 0, address(this).balance);

        uint256 callerBalanceBefore = address(this).balance;

        // Attempt to call sendTo
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amountBound));

        uint256 callerBalanceAfter = address(this).balance;

        // General rule: if the call succeeded, caller's balance decreased by amountBound; if it reverted, balance unchanged
        if (success) {
            assertTrue(callerBalanceBefore - callerBalanceAfter == amountBound, "Caller balance should decrease by amount");
        } else {
            assertTrue(callerBalanceBefore == callerBalanceAfter, "Caller balance should remain unchanged on revert");
        }
    }
}

