pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict to owner calling (since only owner can call sendTo)
        vm.assume(amount < address(this).balance);

        // Record sender balance before call
        uint256 senderBalanceBefore = address(this).balance;

        // Call sendTo (this contract is the owner because it deployed C)
        c.sendTo(receiver, amount);

        // Record sender balance after call
        uint256 senderBalanceAfter = address(this).balance;

        // The rule: if the call succeeded (did not revert), sender's balance decreased by exactly the amount
        assertTrue(senderBalanceBefore - senderBalanceAfter == amount, "Sender balance should decrease by the exact amount on successful sendTo");
    }
}

